      "content": "import { describe, expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';

describe('Task.create', () => {
  test(
    covers(
      ['criterion:0001/titulo-invalido', 'invariant:Task/titulo-obrigatorio'],
      'rejeita titulo vazio ou so com espacos com TASK_TITLE_REQUIRED',
    ),
    () => {
      for (const title of ['', '   ']) {
        try {
          Task.create('t1', title);
          throw new Error('Expected Task.create to throw');
        } catch (error) {
          expect(error).toBeInstanceOf(DomainError);
          expect((error as DomainError).code).toBe('TASK_TITLE_REQUIRED');
        }
      }
    },
  );

  test(
    covers(['criterion:0001/criacao', 'method:Task.create'], 'cria tarefa pending, normaliza titulo e registra TaskCreated'),
    () => {
      const task = Task.create('t1', '  Minha tarefa  ');

      expect(task.id).toBe('t1');
      expect(task.title).toBe('Minha tarefa');
      expect(task.status).toBe('pending');

      const [event] = task.pullEvents();
      expect(event).toBeInstanceOf(TaskCreated);
      expect(event?.payload).toEqual({ taskId: 't1', title: 'Minha tarefa' });
    },
  );
});
